CREATE OR REPLACE FUNCTION public.approve_temp_sighting(temp_sighting_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  new_sighting_id int;
  new_manta_id uuid;
  new_photo_id uuid;
  temp_manta record;
  temp_photo record;
begin
  -- Insert into sightings
  insert into sightings (sighting_date, start_time, end_time, sitelocation, island, latitude, longitude, photographer, email, notes)
  select sighting_date, start_time, end_time, sitelocation, island, latitude, longitude, photographer, email, notes
  from temp_sightings
  where temp_sighting_id = approve_temp_sighting.temp_sighting_id
  returning pk_sighting_id into new_sighting_id;

  -- For each manta
  for temp_manta in select * from temp_mantas where fk_temp_sighting_id = temp_sighting_id loop
    insert into mantas (catalog_id, sighting_id, is_new_individual)
    values (temp_manta.catalog_id, new_sighting_id, temp_manta.is_new_individual)
    returning manta_id into new_manta_id;

    -- Insert photos
    for temp_photo in select * from temp_photos where fk_temp_manta_id = temp_manta.temp_manta_id loop
      insert into photos (photo_id, manta_id, photo_url, is_best_sighting_photo, is_best_catalog_photo)
      values (
        uuid_generate_v4(),
        new_manta_id,
        temp_photo.photo_url,
        temp_photo.is_best_sighting_photo,
        temp_photo.is_best_catalog_photo
      )
      returning photo_id into new_photo_id;

      -- Optionally: Insert into catalog if new
      if temp_manta.is_new_individual and temp_photo.is_best_catalog_photo then
        insert into catalog (name, best_photo_id)
        values (null, new_photo_id);
      end if;

    end loop;
  end loop;

  -- Archive instead of delete
  update temp_sightings set status = 'processed' where temp_sighting_id = approve_temp_sighting.temp_sighting_id;
end;
$function$

