CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  c jsonb := auth.jwt();
begin
  -- Prefer app_metadata.role === 'admin'
  if c ? 'app_metadata' then
    if (c->'app_metadata'->>'role') = 'admin' then
      return true;
    end if;
    -- tolerate common boolean flag (if used)
    if (c->'app_metadata'->>'is_admin') = 'true' then
      return true;
    end if;
  end if;
  -- fallback: custom claim at root (if present)
  if (c->>'role') = 'admin' then
    return true;
  end if;
  if (c->>'is_admin') = 'true' then
    return true;
  end if;

  return false;
end $function$

CREATE OR REPLACE FUNCTION public.trg_catalog_total_biopsies()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (tg_op = 'INSERT') then
    if new.fk_catalog_id is not null then
      update public.catalog
        set total_biopsies = coalesce(total_biopsies,0) + 1
        where pk_catalog_id = new.fk_catalog_id;
    end if;
    return new;
  elsif (tg_op = 'DELETE') then
    if old.fk_catalog_id is not null then
      update public.catalog
        set total_biopsies = greatest(coalesce(total_biopsies,0) - 1, 0)
        where pk_catalog_id = old.fk_catalog_id;
    end if;
    return old;
  elsif (tg_op = 'UPDATE') then
    if old.fk_catalog_id is distinct from new.fk_catalog_id then
      if old.fk_catalog_id is not null then
        update public.catalog
          set total_biopsies = greatest(coalesce(total_biopsies,0) - 1, 0)
          where pk_catalog_id = old.fk_catalog_id;
      end if;
      if new.fk_catalog_id is not null then
        update public.catalog
          set total_biopsies = coalesce(total_biopsies,0) + 1
          where pk_catalog_id = new.fk_catalog_id;
      end if;
    end if;
    return new;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.commit_sighting_submission(sub_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  submission_row public.sighting_submissions%rowtype;
  manta jsonb;
  photo jsonb;

  new_sighting_id integer;
  new_manta_id integer;
  resolved_catalog_id integer;
  proposed_species text;
  catalog_species text;
  resolved_sitelocation text;
  resolved_storage_path text;
  resolved_file_name text;
  transform jsonb;
  field_name text;
  numeric_value numeric;
  -- BEGIN size-evidence declarations
  new_photo_id integer;
  new_size_id bigint;
  new_size_ids bigint[];
  encounter_date date;
  measurement jsonb;
  measurement_point jsonb;
  measured_photo_uuid uuid;
  -- END size-evidence declarations
begin
  if auth.uid() is null or not public.is_admin_user() then
    raise exception using errcode = '42501', message = 'An active administrator is required to commit a sighting';
  end if;
  select *
  into submission_row
  from public.sighting_submissions
  where id = sub_id
  for update;

  if not found then
    raise exception 'Submission not found';
  end if;

  if submission_row.status = 'committed' and submission_row.committed_pk_sighting_id is not null then
    return;
  end if;

  if submission_row.status is distinct from 'pending'
     or submission_row.committed_pk_sighting_id is not null then
    raise exception 'Only a pending, uncommitted submission can be committed';
  end if;

  resolved_sitelocation :=
    nullif(
      trim(
        coalesce(
          submission_row.payload->>'sitelocation',
          submission_row.payload->>'locationName'
        )
      ),
      ''
    );

  -- Legacy absent/null/empty values remain NULL; never infer from times.
  if nullif(submission_row.payload->>'standardize_survey', '') is not null
     and submission_row.payload->>'standardize_survey' not in ('Yes', 'No') then
    raise exception 'standardize_survey must be Yes, No, or empty';
  end if;

  insert into public.sightings (
    sighting_date,
    start_time,
    end_time,
    standardize_survey,
    photographer,
    island,
    sitelocation,
    latitude,
    longitude,
    location_unknown,
    notes
  )
  values (
    coalesce(
      submission_row.sighting_date,
      nullif(submission_row.payload->>'date', '')::date
    ),
    nullif(submission_row.payload->>'startTime', ''),
    nullif(submission_row.payload->>'stopTime', ''),
    nullif(submission_row.payload->>'standardize_survey', ''),
    nullif(submission_row.payload->>'photographer', ''),
    nullif(submission_row.payload->>'island', ''),
    resolved_sitelocation,
    nullif(submission_row.payload->>'latitude', '')::numeric,
    nullif(submission_row.payload->>'longitude', '')::numeric,
    coalesce(nullif(submission_row.payload->>'location_unknown', '')::boolean, false),
    nullif(submission_row.payload->>'notes', '')
  )
  returning pk_sighting_id, sighting_date into new_sighting_id, encounter_date;

  for manta in
    select value
    from jsonb_array_elements(coalesce(submission_row.payload->'mantas', '[]'::jsonb))
  loop
    resolved_catalog_id := null;
    proposed_species := nullif(manta->>'species', '');
    if proposed_species is not null and proposed_species not in ('mobula alfredi', 'mobula birostris') then
      raise exception 'Proposed catalog species must be mobula alfredi, mobula birostris, or empty';
    end if;

    if coalesce((manta->>'noMatch')::boolean, false) = true then
      insert into public.catalog (name, species)
      values (
        coalesce(
          nullif(manta->>'name', ''),
          'Pending Name'
        ),
        proposed_species
      )
      returning pk_catalog_id into resolved_catalog_id;
    else
      resolved_catalog_id :=
        coalesce(
          nullif(manta->>'matchedCatalogId', '')::integer,
          nullif(manta->>'potentialCatalogId', '')::integer,
          nullif(manta->>'suggested_catalog_id', '')::integer
        );

      if resolved_catalog_id is null then
        raise exception
          'Cannot commit submission %: manta % has no resolved catalog match and is not marked noMatch',
          sub_id,
          coalesce(manta->>'id', '(no manta id)');
      end if;
      -- Catalog identity is authoritative; compare legacy spellings without rewriting.
      select case lower(btrim(species))
        when 'alfredi' then 'mobula alfredi'
        when 'birostris' then 'mobula birostris'
        else nullif(lower(btrim(species)), '')
      end into catalog_species
      from public.catalog where pk_catalog_id = resolved_catalog_id
      for share;
      if proposed_species is not null and catalog_species is not null
         and proposed_species <> catalog_species then
        raise exception 'Species mismatch: proposed species differs from matched catalog species. Correct the proposal or catalog match before approval.';
      end if;
    end if;

    insert into public.mantas (
      fk_sighting_id,
      fk_catalog_id,
      submission_manta_id,
      gender,
      age_class,
      size_dw_m
    )
    values (
      new_sighting_id,
      resolved_catalog_id,
      nullif(btrim(manta->>'id'), ''),
      nullif(manta->>'gender', ''),
      nullif(manta->>'ageClass', ''),
      nullif(manta->>'size', '')::numeric
    )
    returning pk_manta_id into new_manta_id;

    new_size_ids := array[]::bigint[]; -- size-evidence: reset per manta

    for photo in
      select value
      from jsonb_array_elements(coalesce(manta->'photos', '[]'::jsonb))
    loop
      resolved_storage_path :=
        nullif(
          coalesce(
            photo->>'path',
            photo->>'url'
          ),
          ''
        );

      resolved_file_name :=
        coalesce(
          nullif(photo->>'name', ''),
          nullif(photo->>'id', ''),
          'uploaded-photo'
        );

      if resolved_storage_path is null then
        raise exception
          'Cannot commit submission %: photo for manta % is missing path/url',
          sub_id,
          coalesce(manta->>'id', '(no manta id)');
      end if;

      -- Presence of ANY new field opts into strict provenance validation.
      -- Partial/null provenance must never silently fall back to legacy behavior.
      if photo ?| array['storageBucket', 'originalPath', 'editTransform'] then
        if jsonb_typeof(photo->'id') is distinct from 'string'
           or (photo->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           or jsonb_typeof(photo->'storageBucket') is distinct from 'string'
           or (photo->>'storageBucket') is distinct from 'manta-images' then
          raise exception 'Provenance photo requires a UUID and manta-images bucket';
        end if;

        foreach field_name in array array['path', 'originalPath'] loop
          if jsonb_typeof(photo->field_name) is distinct from 'string'
             or btrim(photo->>field_name) = ''
             or (photo->>field_name) <> btrim(photo->>field_name)
             or (photo->>field_name) ~ '(^/|://|[?#]|(^|/)\.\.(/|$))'
             or strpos(photo->>field_name, chr(92)) > 0 then
            raise exception 'Provenance photo requires bucket-relative prepared and original paths';
          end if;
        end loop;
        if photo->>'path' = photo->>'originalPath' then
          raise exception 'Prepared and original paths must be distinct';
        end if;

        transform := photo->'editTransform';
        if jsonb_typeof(transform) is distinct from 'object'
           or (transform->>'version') is distinct from 'rotate-crop-v1'
           or jsonb_typeof(transform->'crop') is distinct from 'object' then
          raise exception 'Provenance photo requires a rotate-crop-v1 transform';
        end if;
        foreach field_name in array array[
          'rotationDegrees', 'originalWidth', 'originalHeight', 'exifOrientation',
          'rotatedWidth', 'rotatedHeight', 'outputWidth', 'outputHeight'
        ] loop
          if jsonb_typeof(transform->field_name) is distinct from 'number' then
            raise exception 'Missing or nonnumeric transform field: %', field_name;
          end if;
          if field_name <> 'rotationDegrees' then
            numeric_value := (transform->>field_name)::numeric;
            if numeric_value <= 0 or numeric_value <> trunc(numeric_value) then
              raise exception 'Transform dimensions/orientation must be positive integers';
            end if;
          end if;
        end loop;
        if (transform->>'exifOrientation')::numeric > 8 then
          raise exception 'EXIF orientation must be between 1 and 8';
        end if;
        foreach field_name in array array['x', 'y', 'width', 'height'] loop
          if jsonb_typeof(transform->'crop'->field_name) is distinct from 'number' then
            raise exception 'Missing or nonnumeric crop field: %', field_name;
          end if;
          numeric_value := (transform->'crop'->>field_name)::numeric;
          if numeric_value < 0 or numeric_value <> trunc(numeric_value)
             or (field_name in ('width', 'height') and numeric_value = 0) then
            raise exception 'Crop must use nonnegative integer pixels and positive dimensions';
          end if;
        end loop;
        if (transform->'crop'->>'x')::numeric + (transform->'crop'->>'width')::numeric
             > (transform->>'rotatedWidth')::numeric
           or (transform->'crop'->>'y')::numeric + (transform->'crop'->>'height')::numeric
             > (transform->>'rotatedHeight')::numeric then
          raise exception 'Crop exceeds rotated canvas';
        end if;

        -- Existing UNIQUE(pk_photo_uuid) rejects conflicting reuse, including
        -- concurrent inserts. No upsert, replacement, or second photo row.
        insert into public.photos (
          pk_photo_uuid, fk_manta_id, fk_sighting_id, fk_catalog_id,
          storage_path, storage_bucket, original_storage_path, edit_transform,
          file_name2, photo_view, is_best_manta_ventral_photo, is_best_manta_dorsal_photo
        ) values (
          (photo->>'id')::uuid, new_manta_id, new_sighting_id, resolved_catalog_id,
          photo->>'path', photo->>'storageBucket', photo->>'originalPath', transform,
          resolved_file_name, coalesce(nullif(photo->>'view', ''), 'ventral'),
          coalesce((photo->>'isBestVentral')::boolean, false),
          coalesce((photo->>'isBestDorsal')::boolean, false)
        ) returning pk_photo_id into new_photo_id;
      else
        -- Legacy bucket/UUID defaults are unchanged; missing best-dorsal defaults false.
      insert into public.photos (
        fk_manta_id,
        fk_sighting_id,
        fk_catalog_id,
        storage_path,
        file_name2,
        photo_view,
        is_best_manta_ventral_photo,
        is_best_manta_dorsal_photo
      )
      values (
        new_manta_id,
        new_sighting_id,
        resolved_catalog_id,
        resolved_storage_path,
        resolved_file_name,
        coalesce(nullif(photo->>'view', ''), 'ventral'),
        coalesce((photo->>'isBestVentral')::boolean, false),
        coalesce((photo->>'isBestDorsal')::boolean, false)
      ) returning pk_photo_id into new_photo_id;
      end if;
      -- BEGIN size-evidence persistence
      measurement := photo->'measure';
      if measurement is not null and measurement <> 'null'::jsonb then
        if jsonb_typeof(measurement) is distinct from 'object' then
          raise exception 'Photo measurement must be an object';
        end if;
        if jsonb_typeof(photo->'id') is distinct from 'string'
           or (photo->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          raise exception 'Measured photo requires a stable UUID';
        end if;
        measured_photo_uuid := (photo->>'id')::uuid;
        foreach field_name in array array['scaleCm', 'scalePx', 'discPx', 'dlCm', 'dwCm'] loop
          if jsonb_typeof(measurement->field_name) is distinct from 'number' then
            raise exception 'Missing or nonnumeric measurement field: %', field_name;
          end if;
          numeric_value := (measurement->>field_name)::numeric;
          if not (numeric_value > 0 and numeric_value < 'Infinity'::numeric) then
            raise exception 'Measurement field must be finite and positive: %', field_name;
          end if;
        end loop;
        -- Older pending measurements have numeric evidence but no saved endpoints.
        if measurement->'points' is not null and measurement->'points' <> 'null'::jsonb then
          if jsonb_typeof(measurement->'points') is distinct from 'array' then
            raise exception 'Measurement points must be an array';
          end if;
          if jsonb_array_length(measurement->'points') <> 4 then
            raise exception 'Measurement requires exactly four points when present';
          end if;
          for measurement_point in select value from jsonb_array_elements(measurement->'points') loop
            foreach field_name in array array['x', 'y'] loop
              if jsonb_typeof(measurement_point->field_name) is distinct from 'number' then
                raise exception 'Measurement point coordinates must be numeric';
              end if;
              numeric_value := (measurement_point->>field_name)::numeric;
              if not (numeric_value >= 0 and numeric_value <= 1) then
                raise exception 'Measurement point coordinates must be normalized';
              end if;
            end loop;
          end loop;
        end if;

        insert into public.manta_sizes (
          fk_manta_id, source_photo_id, measurement_method, measurement_type,
          size_m, standardized_dw_m, measured_on, row_sig, measurement_evidence
        ) values (
          new_manta_id, new_photo_id, 'paired_laser', 'length',
          (measurement->>'dlCm')::numeric / 100,
          (measurement->>'dwCm')::numeric / 100,
          encounter_date,
          'submission:' || sub_id::text || ':photo:' || measured_photo_uuid::text || ':paired_laser:v1',
          jsonb_strip_nulls(jsonb_build_object(
            'version', 1,
            'scaleCm', measurement->'scaleCm',
            'scalePx', measurement->'scalePx',
            'discPx', measurement->'discPx',
            'points', measurement->'points',
            'conversion', jsonb_build_object('formula', 'DW = DL × 2.3', 'ratio', 2.3),
            'source', jsonb_build_object(
              'photoUuid', measured_photo_uuid::text,
              'storageBucket', photo->'storageBucket',
              'storagePath', photo->'path',
              'originalStoragePath', photo->'originalPath',
              'outputWidth', photo->'editTransform'->'outputWidth',
              'outputHeight', photo->'editTransform'->'outputHeight'
            )
          ))
        ) returning pk_manta_size_id into new_size_id;
        new_size_ids := array_append(new_size_ids, new_size_id);
      end if;
      -- END size-evidence persistence
    end loop;
    -- BEGIN size-evidence encounter mean
    -- Only IDs inserted for this new encounter; no historical/imported evidence.
    if cardinality(new_size_ids) > 0 then
      update public.mantas
      set size_dw_m = (
        select avg(standardized_dw_m) from public.manta_sizes
        where pk_manta_size_id = any(new_size_ids)
      )
      where pk_manta_id = new_manta_id;
    end if;
    -- END size-evidence encounter mean
  end loop;

  update public.sighting_submissions
  set
    status = 'committed',
    committed_at = now(),
    committed_pk_sighting_id = new_sighting_id
  where id = sub_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_sighting_total_mantas()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_old_sighting_id integer;
  v_new_sighting_id integer;
begin
  v_old_sighting_id := case
    when tg_op in ('UPDATE', 'DELETE') then old.fk_sighting_id
    else null
  end;

  v_new_sighting_id := case
    when tg_op in ('INSERT', 'UPDATE') then new.fk_sighting_id
    else null
  end;

  if v_old_sighting_id is not null then
    update public.sightings s
    set total_mantas = (
      select count(*)
      from public.mantas m
      where m.fk_sighting_id = v_old_sighting_id
    )
    where s.pk_sighting_id = v_old_sighting_id;
  end if;

  if v_new_sighting_id is not null
     and v_new_sighting_id is distinct from v_old_sighting_id then
    update public.sightings s
    set total_mantas = (
      select count(*)
      from public.mantas m
      where m.fk_sighting_id = v_new_sighting_id
    )
    where s.pk_sighting_id = v_new_sighting_id;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reset_false_committed_submission(sub_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  sub_record record;
begin
  select *
  into sub_record
  from public.sighting_submissions
  where id = sub_id;

  if sub_record is null then
    raise exception 'Submission not found';
  end if;

  if coalesce(sub_record.status, '') <> 'committed' then
    raise exception 'Submission is not marked committed';
  end if;

  if sub_record.committed_pk_sighting_id is not null then
    raise exception 'Submission has a real committed sighting and cannot be reset with this function';
  end if;

  update public.sighting_submissions
  set
    status = 'pending',
    committed_at = null
  where id = sub_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_sighting_location_columns()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_location_changed boolean := false;
  v_sitelocation_changed boolean := false;
  v_location text := nullif(btrim(new.location), '');
  v_sitelocation text := nullif(btrim(new.sitelocation), '');
begin
  if tg_op = 'UPDATE' then
    v_location_changed := new.location is distinct from old.location;
    v_sitelocation_changed := new.sitelocation is distinct from old.sitelocation;
  end if;

  if tg_op = 'INSERT' or (v_location_changed and not v_sitelocation_changed) then
    if v_location is not null and v_sitelocation is null then
      new.sitelocation := new.location;
    end if;
  end if;

  if tg_op = 'INSERT' or (v_sitelocation_changed and not v_location_changed) then
    if v_sitelocation is not null and v_location is null then
      new.location := new.sitelocation;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_manta_size_catalog_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.fk_manta_id is null then
    new.fk_catalog_id := null;
  else
    select m.fk_catalog_id
      into new.fk_catalog_id
    from public.mantas m
    where m.pk_manta_id = new.fk_manta_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_profile_access(target_user_id uuid, requested_role text, requested_is_active boolean, change_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  actor_profile public.profiles%rowtype;
  target_profile public.profiles%rowtype;
  active_admin_count integer;
  event_name text;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('manta-active-admin-floor'));
  select * into actor_profile from public.profiles where id = actor_id for share;
  if not found then raise exception 'Acting account has no application profile'; end if;
  if actor_profile.role <> 'admin' or actor_profile.is_active is not true then
    raise exception 'Active administrator access is required';
  end if;
  if requested_role not in ('admin', 'user') then raise exception 'Invalid application role'; end if;
  if change_reason is null or char_length(pg_catalog.btrim(change_reason)) not between 3 and 500 then
    raise exception 'A valid change reason is required';
  end if;

  select * into target_profile from public.profiles where id = target_user_id for update;
  if not found then raise exception 'Target application profile does not exist'; end if;
  if actor_id = target_user_id and target_profile.role = 'admin' and target_profile.is_active is true
     and (requested_role <> 'admin' or requested_is_active is not true) then
    raise exception 'Administrators cannot demote, suspend, or deactivate themselves';
  end if;
  if target_profile.role = 'admin' and target_profile.is_active is true
     and (requested_role <> 'admin' or requested_is_active is not true) then
    select count(*) into active_admin_count
    from public.profiles where role = 'admin' and is_active is true;
    if active_admin_count <= 1 then raise exception 'At least one active administrator must remain'; end if;
  end if;

  update public.profiles set role = requested_role, is_active = requested_is_active
  where id = target_user_id;
  event_name := case
    when target_profile.is_active is true and requested_is_active is false then 'suspension'
    when target_profile.is_active is false and requested_is_active is true then 'reactivation'
    else 'role_change'
  end;
  insert into public.user_access_audit (event_type, actor_user_id, target_user_id, outcome, reason, details)
  values (
    event_name, actor_id, target_user_id, 'success', pg_catalog.btrim(change_reason),
    pg_catalog.jsonb_build_object(
      'old_role', target_profile.role, 'new_role', requested_role,
      'old_active', target_profile.is_active, 'new_active', requested_is_active
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_imports_commit_drone_photos(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null or not exists (
    select 1 from public.profiles
    where id = actor_id and role = 'admin' and is_active is true
  ) then
    raise exception using
      errcode = '42501',
      message = 'Active administrator access is required';
  end if;

  return private.fn_imports_commit_drone_photos_impl(p_batch);
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_sighting_submission_with_biopsies(sub_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  submission_row public.sighting_submissions%rowtype;
  manta_payload jsonb;
  biopsy_payload jsonb;
  parent_manta_id integer;
  parent_catalog_id integer;
  new_sighting_id integer;
  expected_biopsies integer;
  existing_biopsies integer;
  biopsy_count integer := 0;
begin
  if actor_id is null or not public.is_admin_user() then
    raise exception using
      errcode = '42501',
      message = 'An active administrator is required to commit biopsy data';
  end if;

  select * into submission_row
  from public.sighting_submissions
  where id = sub_id
  for update;
  if not found then raise exception 'Submission not found'; end if;

  select count(*) into expected_biopsies
  from jsonb_array_elements(coalesce(submission_row.payload->'mantas', '[]'::jsonb)) item
  where item ? 'biopsy' and item->'biopsy' <> 'null'::jsonb;

  if expected_biopsies = 0 then
    perform public.commit_sighting_submission(sub_id);
    return;
  end if;

  if submission_row.status = 'committed'
     and submission_row.committed_pk_sighting_id is not null then
    select count(*) into existing_biopsies
    from public.biopsies b
    join public.mantas m on m.pk_manta_id = b.fk_manta_id
    join lateral jsonb_array_elements(
      coalesce(submission_row.payload->'mantas', '[]'::jsonb)
    ) item on item->>'id' = m.submission_manta_id
    where b.fk_sighting_id = submission_row.committed_pk_sighting_id
      and b.source = 'organic_sighting'
      and item ? 'biopsy' and item->'biopsy' <> 'null'::jsonb;
    if existing_biopsies = expected_biopsies then return; end if;
    raise exception 'Committed submission has incomplete or ambiguous biopsy mapping';
  end if;

  perform public.commit_sighting_submission(sub_id);
  select committed_pk_sighting_id into new_sighting_id
  from public.sighting_submissions where id = sub_id;
  if new_sighting_id is null then
    raise exception 'Sighting commit did not create a parent sighting';
  end if;

  for manta_payload in
    select value from jsonb_array_elements(coalesce(submission_row.payload->'mantas', '[]'::jsonb))
  loop
    biopsy_payload := manta_payload->'biopsy';
    if biopsy_payload is null or biopsy_payload = 'null'::jsonb then continue; end if;

    select m.pk_manta_id, m.fk_catalog_id
      into parent_manta_id, parent_catalog_id
    from public.mantas m
    where m.fk_sighting_id = new_sighting_id
      and m.submission_manta_id = manta_payload->>'id';

    if not found or parent_manta_id is null then
      raise exception 'No committed manta matches biopsy correlation ID';
    end if;
    if (select count(*) from public.mantas m
        where m.fk_sighting_id = new_sighting_id
          and m.submission_manta_id = manta_payload->>'id') <> 1 then
      raise exception 'Ambiguous committed manta biopsy mapping';
    end if;

    insert into public.biopsies (
      fk_manta_id, fk_sighting_id, fk_catalog_id,
      sample_date, sample_time, collector, method,
      island, location, tissue_type, lab_id, notes, source, raw_sample_id
    ) values (
      parent_manta_id, new_sighting_id, parent_catalog_id,
      (biopsy_payload->>'sampleDate')::date,
      nullif(biopsy_payload->>'sampleTime', '')::time,
      nullif(btrim(biopsy_payload->>'collector'), ''),
      nullif(btrim(biopsy_payload->>'method'), ''),
      nullif(btrim(submission_row.payload->>'island'), ''),
      nullif(btrim(coalesce(
        submission_row.payload->>'sitelocation',
        submission_row.payload->>'locationName'
      )), ''),
      nullif(btrim(biopsy_payload->>'tissueType'), ''),
      nullif(btrim(biopsy_payload->>'labId'), ''),
      nullif(btrim(biopsy_payload->>'notes'), ''),
      'organic_sighting',
      nullif(btrim(biopsy_payload->>'sampleId'), '')
    );
    biopsy_count := biopsy_count + 1;
  end loop;

  if biopsy_count <> expected_biopsies then
    raise exception 'Biopsy mapping count mismatch';
  end if;
  update public.sightings
  set total_mantas_biopsied = biopsy_count
  where pk_sighting_id = new_sighting_id;

  -- Force the deferred integrity check before returning success to the caller.
  set constraints public.trg_validate_committed_biopsy_mapping immediate;
  set constraints public.trg_validate_committed_biopsy_mapping deferred;
end;
$function$
